  const setChannelMasterVolume = (
    channelId: MixerTakeChannelKey,
    nextValue: number,
  ) => {
    switch (channelId) {
      case "song":
        setSongMasterVolume(nextValue);
        return;
      case "stream":
        setStreamMasterVolume(nextValue);
        return;
      case "instants":
        setInstantMasterVolume(nextValue);
        return;
      case "sceneInstant":
