      if (cachedDuration !== undefined) {
        setInstantDurationsMs((prev) =>
          prev[instant.id] === cachedDuration
            ? prev
            : { ...prev, [instant.id]: cachedDuration },
        );
        return;
      }

      const audio = new Audio();
      const cleanup = () => {
        audio.onloadedmetadata = null;
        audio.onerror = null;
        audio.src = "";
