// Shared stand-ins for the control route specs (gaulatti/alcantara#194). Kept
// outside app/ so they are not part of the coverage denominator.
import { vi } from "vitest";

export type Answer = Response | (() => Response | Promise<Response>);

export interface ControlServer {
  calls: { method: string; path: string; body: unknown }[];
  answers: Map<string, Answer>;
  /** Set or replace the answer for `METHOD /path` (query string included). */
  answer(key: string, value: Answer): void;
  /** Requests for one `METHOD /path`, in order. */
  requests(key: string): unknown[];
}

/**
 * One fetch stand-in for every request the console makes, keyed by
 * `METHOD /path?query`. Unknown requests answer 404, so a missing fixture shows
 * up as a refused request instead of a thrown test.
 */
export function controlServer(defaults: Record<string, Answer>): ControlServer {
  const calls: ControlServer["calls"] = [];
  const answers = new Map<string, Answer>(Object.entries(defaults));
  vi.stubGlobal(
    "fetch",
    vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
      const url = new URL(String(input), "http://localhost");
      const method = (init?.method ?? "GET").toUpperCase();
      const path = decodeURIComponent(url.pathname) + url.search;
      let body: unknown = null;
      if (typeof init?.body === "string") {
        try {
          body = JSON.parse(init.body);
        } catch {
          body = init.body;
        }
      }
      calls.push({ method, path, body });
      const answer = answers.get(`${method} ${path}`);
      if (!answer) return new Response("not found", { status: 404 });
      return typeof answer === "function" ? answer() : answer.clone();
    }),
  );
  return {
    calls,
    answers,
    answer(key, value) {
      answers.set(key, value);
    },
    requests(key) {
      return calls
        .filter((call) => `${call.method} ${call.path}` === key)
        .map((call) => call.body);
    },
  };
}

/** Browser APIs jsdom lacks that the console's panels use while mounting. */
export function stubConsoleBrowser() {
  vi.stubGlobal(
    "ResizeObserver",
    class {
      observe() {}
      unobserve() {}
      disconnect() {}
    },
  );
}

/** A WebSocket stand-in the test opens, feeds and closes. */
export class FakeSocket {
  static OPEN = 1;
  static instances: FakeSocket[] = [];
  readyState = 0;
  closed = false;
  listeners = new Map<string, ((event: unknown) => void)[]>();
  constructor(readonly url: string) {
    FakeSocket.instances.push(this);
  }
  addEventListener(type: string, listener: (event: unknown) => void) {
    this.listeners.set(type, [...(this.listeners.get(type) ?? []), listener]);
  }
  emit(type: string, event: unknown = {}) {
    for (const listener of this.listeners.get(type) ?? []) listener(event);
  }
  open() {
    this.readyState = FakeSocket.OPEN;
    this.emit("open");
  }
  send(payload: unknown) {
    this.emit("message", {
      data: typeof payload === "string" ? payload : JSON.stringify(payload),
    });
  }
  close() {
    this.closed = true;
    this.readyState = 3;
  }
}

import { useEffect, useRef, useState } from 'react';

interface UseSSEOptions {
  url: string;
  onMessage?: (data: any) => void;
  onConnectionChange?: (isConnected: boolean) => void;
  onConnectionStateChange?: (state: SSEConnectionState) => void;
  reconnectInterval?: number;
  enabled?: boolean;
}

export type SSEConnectionState = 'connecting' | 'connected' | 'disconnected';

export function useSSE({ url, onMessage, onConnectionChange, onConnectionStateChange, reconnectInterval = 3000, enabled = true }: UseSSEOptions) {
  const [isConnected, setIsConnected] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const onMessageRef = useRef(onMessage);
  const onConnectionChangeRef = useRef(onConnectionChange);
  const onConnectionStateChangeRef = useRef(onConnectionStateChange);

  useEffect(() => {
    onMessageRef.current = onMessage;
  }, [onMessage]);

  useEffect(() => {
    onConnectionChangeRef.current = onConnectionChange;
  }, [onConnectionChange]);

  useEffect(() => {
    onConnectionStateChangeRef.current = onConnectionStateChange;
  }, [onConnectionStateChange]);

  useEffect(() => {
    if (!enabled) {
      setIsConnected(false);
      setError(null);
      onConnectionChangeRef.current?.(false);
      onConnectionStateChangeRef.current?.('disconnected');
      return;
    }

    let disposed = false;
    let eventSource: EventSource | null = null;
    let reconnectTimer: number | null = null;
    setIsConnected(false);
    onConnectionChangeRef.current?.(false);
    onConnectionStateChangeRef.current?.('connecting');

    const connect = () => {
      if (disposed) {
        return;
      }

      try {
        eventSource = new EventSource(url);

        eventSource.onopen = () => {
          if (disposed) {
            return;
          }
          setIsConnected(true);
          onConnectionChangeRef.current?.(true);
          onConnectionStateChangeRef.current?.('connected');
          setError(null);
        };

        eventSource.onmessage = (event) => {
          try {
            const data = JSON.parse(event.data);
            onMessageRef.current?.(data);
          } catch (err) {
            console.error('Failed to parse SSE data:', err);
          }
        };

        eventSource.onerror = () => {
          if (disposed) {
            return;
          }
          setIsConnected(false);
          onConnectionChangeRef.current?.(false);
          onConnectionStateChangeRef.current?.('disconnected');
          setError(new Error('SSE connection error'));
          eventSource?.close();
          eventSource = null;

          if (!disposed) {
            reconnectTimer = window.setTimeout(connect, reconnectInterval);
          }
        };
      } catch (err) {
        setIsConnected(false);
        onConnectionChangeRef.current?.(false);
        onConnectionStateChangeRef.current?.('disconnected');
        setError(err as Error);
        if (!disposed) {
          reconnectTimer = window.setTimeout(connect, reconnectInterval);
        }
      }
    };

    connect();

    return () => {
      disposed = true;
      if (reconnectTimer !== null) {
        window.clearTimeout(reconnectTimer);
      }
      eventSource?.close();
    };
  }, [enabled, url, reconnectInterval]);

  return { isConnected, error };
}

import { useCallback } from "react";
import { useConsolePreferences } from "../contexts/ConsolePreferencesContext";

export function useGlobalProgramId() {
  const { profile, updateProfile } = useConsolePreferences();
  const setProgramId = useCallback(
    (value: string) => {
      updateProfile({ selectedProgramId: value.trim() || "main" });
    },
    [updateProfile],
  );
  return [profile.selectedProgramId, setProgramId] as const;
}

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { useSelector } from "react-redux";
import { currentUser, isLoaded as isAuthLoaded } from "../state/selectors/auth";
import { getApiBaseUrl } from "../utils/apiBaseUrl";

export type DeviceClass = "desktop" | "tablet" | "phone";
export type ConsoleWorkspace = "director" | "audio" | "graphics" | "compact";
export interface ConsoleProfile {
  workspace: ConsoleWorkspace;
  dockWidth?: number;
  touchMode: boolean;
  shortcutsEnabled: boolean;
  selectedProgramId: string;
  transitions: Record<string, string>;
}
type SyncState = "loading" | "synced" | "saving" | "degraded" | "conflict";
interface ConflictState {
  local: ConsoleProfile;
  authoritative: ConsoleProfile;
  version: number;
}

interface ConsolePreferencesValue {
  deviceClass: DeviceClass;
  detectedDeviceClass: DeviceClass;
  profile: ConsoleProfile;
  version: number;
  syncState: SyncState;
  conflict: ConflictState | null;
  updateProfile(update: Partial<ConsoleProfile>): void;
  setDeviceClassOverride(value: DeviceClass | null): void;
  resetCurrent(): Promise<void>;
  resetAll(): Promise<void>;
  useAuthoritative(): void;
  retryLocal(): void;
  adoptAcknowledged(version: number, profile: ConsoleProfile): void;
}

const Context = createContext<ConsolePreferencesValue | null>(null);
const OVERRIDE_KEY = "alcantara.console.deviceClassOverride";

export function preferenceCacheIdentity(user?: {
  id: string;
  principalId?: string | null;
}): string | undefined {
  return user?.principalId?.trim() || user?.id;
}

export function detectDeviceClass(
  scope?: Pick<Window, "innerWidth" | "navigator">,
): DeviceClass {
  if (!scope) {
    if (typeof window === "undefined") return "desktop";
    scope = window;
  }
  const ua = scope.navigator.userAgent.toLowerCase();
  if (/iphone|ipod|android.+mobile/.test(ua) || scope.innerWidth < 768)
    return "phone";
  if (
    /ipad|tablet/.test(ua) ||
    (scope.navigator.platform === "MacIntel" &&
      scope.navigator.maxTouchPoints > 1) ||
    scope.innerWidth < 1180
  )
    return "tablet";
  return "desktop";
}

export function defaultConsoleProfile(
  deviceClass: DeviceClass,
): ConsoleProfile {
  return {
    workspace: deviceClass === "desktop" ? "director" : "compact",
    ...(deviceClass === "phone"
      ? {}
      : { dockWidth: deviceClass === "desktop" ? 320 : 300 }),
    touchMode: deviceClass !== "desktop",
    shortcutsEnabled: deviceClass === "desktop",
    selectedProgramId: "main",
    transitions: { main: "crescendo-prism" },
  };
}

function readOverride(): DeviceClass | null {
  if (typeof window === "undefined") return null;
  const value = window.localStorage.getItem(OVERRIDE_KEY);
  return value === "desktop" || value === "tablet" || value === "phone"
    ? value
    : null;
}

function cacheKey(subject: string, deviceClass: DeviceClass): string {
  return `alcantara.console.acknowledged.${encodeURIComponent(subject)}.${deviceClass}`;
}

function readCache(
  subject: string,
  deviceClass: DeviceClass,
  storage: Pick<Storage, "getItem"> = window.localStorage,
): { version: number; profile: ConsoleProfile } | null {
  try {
    const value = JSON.parse(
      storage.getItem(cacheKey(subject, deviceClass)) ?? "null",
    ) as { version?: unknown; profile?: unknown } | null;
    if (
      !value ||
      !Number.isSafeInteger(value.version) ||
      !value.profile ||
      typeof value.profile !== "object"
    )
      return null;
    return value as { version: number; profile: ConsoleProfile };
  } catch {
    return null;
  }
}

export function readPreferenceCache(
  user: { id: string; principalId?: string | null } | undefined,
  deviceClass: DeviceClass,
  storage: Pick<Storage, "getItem" | "setItem"> = window.localStorage,
): { version: number; profile: ConsoleProfile } | null {
  const preferredIdentity = preferenceCacheIdentity(user);
  if (!preferredIdentity) return null;

  const preferred = readCache(preferredIdentity, deviceClass, storage);
  if (preferred || !user?.id || preferredIdentity === user.id) return preferred;

  const legacy = readCache(user.id, deviceClass, storage);
  if (!legacy) return null;
  storage.setItem(
    cacheKey(preferredIdentity, deviceClass),
    JSON.stringify(legacy),
  );
  return legacy;
}

export function ConsolePreferencesProvider({
  children,
}: {
  children: ReactNode;
}) {
  const user = useSelector(currentUser);
  const authLoaded = useSelector(isAuthLoaded);
  const preferenceIdentity = preferenceCacheIdentity(user);
  const detectedDeviceClass = useMemo(() => detectDeviceClass(), []);
  const [deviceClass, setDeviceClass] = useState<DeviceClass>(
    () => readOverride() ?? detectedDeviceClass,
  );
  const [profile, setProfile] = useState<ConsoleProfile>(() =>
    defaultConsoleProfile(deviceClass),
  );
  const [version, setVersion] = useState(0);
  const [syncState, setSyncState] = useState<SyncState>("loading");
  const [conflict, setConflict] = useState<ConflictState | null>(null);
  const dirty = useRef(false);
  const profileRef = useRef(profile);
  const versionRef = useRef(version);
  profileRef.current = profile;
  versionRef.current = version;

  const acknowledge = useCallback(
    (subject: string, nextVersion: number, nextProfile: ConsoleProfile) => {
      setVersion(nextVersion);
      setProfile(nextProfile);
      window.localStorage.setItem(
        cacheKey(subject, deviceClass),
        JSON.stringify({ version: nextVersion, profile: nextProfile }),
      );
    },
    [deviceClass],
  );

  useEffect(() => {
    if (!authLoaded || !preferenceIdentity) return;
    dirty.current = false;
    setConflict(null);
    const cached = readPreferenceCache(user, deviceClass);
    if (cached) acknowledge(preferenceIdentity, cached.version, cached.profile);
    else {
      setProfile(defaultConsoleProfile(deviceClass));
      setVersion(0);
    }
    setSyncState("loading");
    void fetch(`${getApiBaseUrl()}/operator-preferences/${deviceClass}`)
      .then(async (response) => {
        if (!response.ok) throw new Error(String(response.status));
        return response.json() as Promise<{
          version: number;
          profile: ConsoleProfile;
        }>;
      })
      .then((payload) => {
        acknowledge(preferenceIdentity, payload.version, payload.profile);
        setSyncState("synced");
      })
      .catch(() => setSyncState("degraded"));
  }, [acknowledge, authLoaded, deviceClass, preferenceIdentity, user]);

  const save = useCallback(async () => {
    if (!preferenceIdentity || !dirty.current || conflict) return;
    dirty.current = false;
    const local = profileRef.current;
    setSyncState("saving");
    try {
      const response = await fetch(
        `${getApiBaseUrl()}/operator-preferences/${deviceClass}`,
        {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ version: versionRef.current, profile: local }),
        },
      );
      if (response.status === 409) {
        const body = (await response.json()) as {
          authoritative: { version: number; profile: ConsoleProfile };
        };
        setConflict({
          local,
          authoritative: body.authoritative.profile,
          version: body.authoritative.version,
        });
        setSyncState("conflict");
        return;
      }
      if (!response.ok) throw new Error(String(response.status));
      const saved = (await response.json()) as {
        version: number;
        profile: ConsoleProfile;
      };
      acknowledge(preferenceIdentity, saved.version, saved.profile);
      setSyncState("synced");
    } catch {
      dirty.current = true;
      setSyncState("degraded");
    }
  }, [acknowledge, conflict, deviceClass, preferenceIdentity]);

  useEffect(() => {
    if (!dirty.current || conflict) return;
    const timer = window.setTimeout(() => void save(), 700);
    return () => window.clearTimeout(timer);
  }, [conflict, profile, save]);

  useEffect(() => {
    if (syncState !== "degraded" || !dirty.current || conflict) return;
    const timer = window.setInterval(() => void save(), 5_000);
    return () => window.clearInterval(timer);
  }, [conflict, save, syncState]);

  useEffect(() => {
    if (
      syncState !== "degraded" ||
      dirty.current ||
      conflict ||
      !preferenceIdentity
    )
      return;
    const timer = window.setInterval(() => {
      void fetch(`${getApiBaseUrl()}/operator-preferences/${deviceClass}`)
        .then(async (response) => {
          if (!response.ok) throw new Error(String(response.status));
          return response.json() as Promise<{
            version: number;
            profile: ConsoleProfile;
          }>;
        })
        .then((payload) => {
          acknowledge(preferenceIdentity, payload.version, payload.profile);
          setSyncState("synced");
        })
        .catch(() => setSyncState("degraded"));
    }, 5_000);
    return () => window.clearInterval(timer);
  }, [acknowledge, conflict, deviceClass, preferenceIdentity, syncState]);

  const updateProfile = useCallback((update: Partial<ConsoleProfile>) => {
    dirty.current = true;
    setProfile((current) => ({ ...current, ...update }));
  }, []);

  const setDeviceClassOverride = useCallback(
    (value: DeviceClass | null) => {
      if (value) window.localStorage.setItem(OVERRIDE_KEY, value);
      else window.localStorage.removeItem(OVERRIDE_KEY);
      setDeviceClass(value ?? detectedDeviceClass);
    },
    [detectedDeviceClass],
  );

  const reset = useCallback(
    async (all: boolean) => {
      if (!user?.id || !preferenceIdentity) return;
      const response = await fetch(
        `${getApiBaseUrl()}/operator-preferences${all ? "" : `/${deviceClass}`}`,
        { method: "DELETE" },
      );
      if (!response.ok) throw new Error(`Reset failed (${response.status})`);
      if (all) {
        (["desktop", "tablet", "phone"] as DeviceClass[]).forEach((target) =>
          [user.id, preferenceIdentity].forEach((identity) =>
            window.localStorage.removeItem(cacheKey(identity, target)),
          ),
        );
      } else {
        [user.id, preferenceIdentity].forEach((identity) =>
          window.localStorage.removeItem(cacheKey(identity, deviceClass)),
        );
      }
      acknowledge(preferenceIdentity, 0, defaultConsoleProfile(deviceClass));
      dirty.current = false;
      setSyncState("synced");
    },
    [acknowledge, deviceClass, preferenceIdentity, user?.id],
  );

  const value: ConsolePreferencesValue = {
    deviceClass,
    detectedDeviceClass,
    profile,
    version,
    syncState,
    conflict,
    updateProfile,
    setDeviceClassOverride,
    resetCurrent: () => reset(false),
    resetAll: () => reset(true),
    useAuthoritative: () => {
      if (!conflict || !preferenceIdentity) return;
      acknowledge(preferenceIdentity, conflict.version, conflict.authoritative);
      setConflict(null);
      setSyncState("synced");
    },
    retryLocal: () => {
      if (!conflict) return;
      setVersion(conflict.version);
      setProfile(conflict.local);
      setConflict(null);
      dirty.current = true;
      setSyncState("degraded");
    },
    adoptAcknowledged: (nextVersion, nextProfile) => {
      if (!preferenceIdentity) return;
      dirty.current = false;
      acknowledge(preferenceIdentity, nextVersion, nextProfile);
      setConflict(null);
      setSyncState("synced");
    },
  };
  return <Context.Provider value={value}>{children}</Context.Provider>;
}

export function useConsolePreferences(): ConsolePreferencesValue {
  const value = useContext(Context);
  if (!value) throw new Error("ConsolePreferencesProvider is missing");
  return value;
}

